body.query:
query InstitutionSearch($query: InstitutionSearchInput, $collectionScope: CollectionSearchInput) {
  institutionSearch(query: $query) {
    count
    limit
    offset
    results {
      ...InstitutionResult
    }
  }
}

fragment InstitutionResult on InstitutionSearchEntity {
  key
  name
  active
  code
  excerpt
  country
  mailingCountry
  collectionCount(query: $collectionScope)
  numberSpecimens
  occurrenceCount
  featuredImageUrl: thumbor(width: 300, height: 200)
  featuredImageLicense
}
